def main(ids_versions_path, out_path):
    iv = json.load(open(ids_versions_path))
    missing = [i for i in iv if i not in AIR]
    extra = [i for i in AIR if i not in iv]
    assert not missing and not extra, (missing, extra)
    writes = [{"op": "update", "collection": "events", "doc_id": i, "data": {"airBrief": AIR[i]}, "if_version": v} for i, v in iv.items()]
    json.dump(writes, open(out_path, "w"), ensure_ascii=False)
    print(len(writes))


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
